public class DynamicProxyDemo {
    public interface Service {
        void execute();
    }

    public static class RealService implements Service {
        @Override
        public void execute() {
            System.out.println("Executing business logic...");
        }
    }

    public static void main(String[] args) {
        Service realService = new RealService();
        Service proxyInstance = (Service) java.lang.reflect.Proxy.newProxyInstance(
            Service.class.getClassLoader(),
            new Class<?>[]{Service.class},
            (proxy, method, methodArgs) -> {
                System.out.println("[LOG] Before method: " + method.getName());
                Object result = method.invoke(realService, methodArgs);
                System.out.println("[LOG] After method");
                return result;
            }
        );
        proxyInstance.execute();
    }
}
